when.condition:
@{
          var ip = context.Request.IpAddress ?? "";
          var isPrivate = ip.StartsWith("10.") || ip.StartsWith("192.168.")
                          || System.Text.RegularExpressions.Regex.IsMatch(ip, "^172\\.(1[6-9]|2[0-9]|3[01])\\.");
          return !isPrivate && context.Request.Headers.GetValueOrDefault("X-Azure-FDID", "") != "{{front-door-id}}";
        }
